package io.syn443.identity

import io.syn443.policy.Policy
import kotlinx.serialization.json.*
import org.junit.Test
import java.math.BigInteger
import java.nio.file.Files
import java.nio.file.Path
import java.security.KeyFactory
import java.security.MessageDigest
import java.security.Signature
import java.security.interfaces.ECPublicKey
import java.security.spec.X509EncodedKeySpec
import java.util.Base64

/** Regenerated by the pinned actual Go producer in the same Actions invocation.
 * No specimen resources, live roots or signed wire values enter diagnostics. */
class AdminOperationGoConformanceTest {
    companion object {
        private const val SOURCE="164347d5c387d05077f43dde07f677d2bc6de47a"
        private val names=listOf("draft-put","draft-discard","preview","publish")
        private val actions=listOf(AdminLayerAction.DRAFT_PUT,AdminLayerAction.DRAFT_DISCARD,AdminLayerAction.PREVIEW,AdminLayerAction.PUBLISH)
        private fun must(value:Boolean,code:String) {if(!value)throw AssertionError(code)}
        private fun text(value:JsonElement)=value.jsonPrimitive.let {require(it.isString);it.content}
        private fun hash(raw:ByteArray)=MessageDigest.getInstance("SHA-256").digest(raw).joinToString(""){"%02x".format(it)}
        private fun invalid(block:()->Unit) {
            try {block()}catch(error:AdminException) {must(error.reason==AdminFailure.INVALID_REPLY,"go_wrong_rejection");return}
            throw AssertionError("go_invalid_input_accepted")
        }
    }
    private class Sample(val value:JsonObject,val raw:ByteArray,val envelope:JsonObject) {
        val name get()=text(value.getValue("name"))
        val version get()=envelope.getValue("version").jsonPrimitive.int
        val requestId get()=text(envelope.getValue("requestId"))
        val action get()=actions.single {it.wire==text(envelope.getValue("action"))}
        val outcomes get()=value.getValue("outcomes").jsonArray.map {it.jsonObject}
        override fun toString()="GoOperationSample([redacted])"
    }
    private class Corpus {
        private class Loaded(val bytes:ByteArray,val root:JsonObject,val actor:String,val origin:String,val now:Long,
            val proposal:AdminLayerProposal,val samples:List<Sample>) {
            override fun toString()="LoadedGoOperationCorpus([redacted])"
        }
        private val loaded=try {
                require(System.getenv("GITHUB_ACTIONS")=="true" && System.getenv("SYN443_OPERATION_SOURCE_SHA")==SOURCE)
                val runner=Path.of(checkNotNull(System.getenv("RUNNER_TEMP"))).toRealPath()
                val ownedPath=Path.of(checkNotNull(System.getenv("SYN443_OPERATION_OWNED")))
                val owned=ownedPath.toRealPath()
                val path=Path.of(checkNotNull(System.getenv("SYN443_OPERATION_FIXTURE")))
                require(!Files.isSymbolicLink(ownedPath) && owned.parent==runner && owned.fileName.toString().startsWith("syn443-operation-wire."))
                require(!Files.isSymbolicLink(path) && path.parent.toRealPath()==owned && path.fileName.toString()=="operations.json")
                require(Files.isRegularFile(path) && Files.size(path) in 1..65536)
                val bytes=Files.readAllBytes(path);require(bytes.size in 1..65536)
                val root=AdminLayerJson.document(Policy.utf8(bytes)).root.jsonObject
                require(root.keys==setOf("schemaVersion","syntheticOnly","nowMs","actor","apiOrigin","proposalWire","previewKeyId","previewRootSpkiB64","originals"))
                require(root["schemaVersion"]==JsonPrimitive(1) && root["syntheticOnly"]==JsonPrimitive(true))
                val actor=text(root.getValue("actor"));val origin=text(root.getValue("apiOrigin"));val now=root.getValue("nowMs").jsonPrimitive.long
                require(now==1_800_000_000_000 && origin=="https://control.example.invalid")
                require(actor==Identity.hash("https://identity.example.invalid/realms/fixture\u0000synthetic-admin".toByteArray()))
                val proposal=AdminLayerControl.proposal(text(root.getValue("proposalWire")))
                val samples=root.getValue("originals").jsonArray.map {item->
                    val value=item.jsonObject
                    require(value.keys==setOf("name","originalBody64","bodyHash","jobId","lookupWire","sealWire","outcomes"))
                    val encoded=text(value.getValue("originalBody64"));val raw=Policy.decode64(encoded)
                    require(raw.size in 1..262144 && Identity.encode(raw)==encoded)
                    val envelope=AdminLayerJson.document(Policy.utf8(raw)).root.jsonObject
                    require(envelope.keys==setOf("version","action","requestId","payload"))
                    Sample(value,raw,envelope)
                }
                require(samples.map {it.name}==(1..2).flatMap {v->names.map {"$it-v$v"}})
                require(samples.sumOf {it.outcomes.size}==36)
                Loaded(bytes,root,actor,origin,now,proposal,samples)
        }catch(_:Exception) {throw AssertionError("go_fixture_missing_or_invalid")}
        val bytes get()=loaded.bytes
        val root get()=loaded.root
        val actor get()=loaded.actor
        val origin get()=loaded.origin
        val now get()=loaded.now
        val proposal get()=loaded.proposal
        val samples get()=loaded.samples
        val time get()=TimeWindow(now,now+1000)
        fun sample(version:Int,action:AdminLayerAction)=samples.single {it.version==version && it.action==action}
        private fun preview(version:Int):AdminLayerPreview {
            val sample=sample(version,AdminLayerAction.PREVIEW)
            val request=AdminLayerControl.preview(proposal,actor,origin,sample.requestId,version)
            val entry=sample.outcomes.single {text(it.getValue("name"))=="RECORDED_READY"}
            val doc=AdminLayerJson.document(text(entry.getValue("wire")))
            val job=doc.root.jsonObject.getValue("job")
            return checkNotNull((AdminLayerControl.parseReply(request,doc.raw(job),time) as AdminLayerJob).preview)
        }
        fun builder(sample:Sample):AdminLayerRequest=when(sample.action) {
            AdminLayerAction.DRAFT_PUT->AdminLayerControl.saveDraft(0,proposal,sample.requestId,sample.version)
            AdminLayerAction.DRAFT_DISCARD->{
                val raw="""{"id":"${proposal.draftId}","revision":1,"proposal":${proposal.wireJson()},"savedAtMs":$now}"""
                val draft=AdminLayerControl.parseReply(AdminLayerControl.getDraft(proposal.draftId,proposal.targetKind,proposal.targetId,Identity.random()),raw,time) as AdminLayerDraft
                AdminLayerControl.discardDraft(draft,sample.requestId,sample.version)
            }
            AdminLayerAction.PREVIEW->AdminLayerControl.preview(proposal,actor,origin,sample.requestId,sample.version)
            AdminLayerAction.PUBLISH->AdminLayerControl.publish(preview(sample.version),actor,origin,sample.requestId,time,sample.version)
            else->error("go_mutation_only")
        }
        fun original(sample:Sample):AdminLayerRequest {
            val canonical=builder(sample)
            return AdminLayerRequest(canonical.action,canonical.requestId,sample.raw,canonical.expected)
        }
        fun request(sample:Sample,intent:AdminOperationIntent=AdminOperationIntent.LOOKUP)=
            AdminOperationReconcile.request(original(sample),actor,origin,Identity.random(),intent)
        fun publicKey():ECPublicKey {
            val encoded=text(root.getValue("previewRootSpkiB64"));val der=Base64.getDecoder().decode(encoded)
            require(der.size==91 && Base64.getEncoder().encodeToString(der)==encoded)
            return (KeyFactory.getInstance("EC").generatePublic(X509EncodedKeySpec(der)) as ECPublicKey).also {
                require(it.params.order==BigInteger("ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551",16) && it.params.cofactor==1 && it.params.curve.field.fieldSize==256)
            }
        }
        override fun toString()="GoOperationCorpus([redacted])"
    }
    private fun verifies(ticket:String,key:ECPublicKey):Boolean=try {
        val parts=ticket.split('.');require(parts.size==3)
        val raw=Policy.decode64(parts[2]);require(raw.size==64)
        val r=BigInteger(1,raw.copyOfRange(0,32));val s=BigInteger(1,raw.copyOfRange(32,64))
        require(r.signum()>0 && r<key.params.order && s.signum()>0 && s<=key.params.order.shiftRight(1))
        fun integer(value:BigInteger):ByteArray {val n=value.toByteArray();return byteArrayOf(2,n.size.toByte())+n}
        val values=integer(r)+integer(s)
        Signature.getInstance("SHA256withECDSA").run {
            initVerify(key);update((parts[0]+"."+parts[1]).toByteArray(Charsets.US_ASCII))
            verify(byteArrayOf(0x30,values.size.toByte())+values)
        }
    }catch(_:Exception) {false}

    @Test fun generatedGoCorpusIsRequiredBoundedOwnedAndPinnedToAcceptedSource() {
        val f=Corpus()
        must(f.bytes.size in 1..65536 && f.samples.size==8 && f.samples.sumOf {it.outcomes.size}==36,"go_corpus_bounds")
        must(f.toString()=="GoOperationCorpus([redacted])" && f.samples.all {it.toString()=="GoOperationSample([redacted])"},"go_redacted_values")
        must(text(f.root.getValue("previewKeyId"))=="synthetic-operation-root","go_public_root_label")
        must(f.publicKey().encoded.size==91,"go_public_spki_bound")
        must(hash(f.bytes).matches(Regex("[a-f0-9]{64}")),"go_fixture_digest")
    }

    @Test fun allEightGoOriginalsRetainExactBytesHashesVersionsAndDerivedJobIds() {
        val f=Corpus()
        for(sample in f.samples) {
            val original=f.original(sample);val request=f.request(sample)
            val exact=sample.raw.copyOf();original.bodyBytes().fill(0);request.original.bodyBytes().fill(0)
            must(original.bodyBytes().contentEquals(exact) && request.original.bodyBytes().contentEquals(exact),"go_original_byte_ownership")
            must(request.originalBodyHash==hash(exact) && request.originalBodyHash==text(sample.value.getValue("bodyHash")),"go_original_hash")
            must(sample.version in 1..2 && request.protocolVersion==sample.version && request.original.expected.replayOnly,"go_original_version")
            val name=names[actions.indexOf(sample.action)]
            must(sample.requestId==Identity.hash("synthetic-operation/v${sample.version}/$name".toByteArray()),"go_original_request_id")
            val job=if(sample.action in listOf(AdminLayerAction.PREVIEW,AdminLayerAction.PUBLISH))Identity.hash((f.actor+"\u0000"+sample.requestId).toByteArray()) else ""
            must(text(sample.value.getValue("jobId"))==job,"go_job_id")
            must(!f.builder(sample).bodyBytes().contentEquals(exact),"go_order_not_substituted")
        }
    }

    @Test fun bothGoReconcileFramesCarryOnlyTheSameOwnedOriginalBytes() {
        val f=Corpus()
        for(sample in f.samples)for(intent in AdminOperationIntent.entries) {
            val key=if(intent==AdminOperationIntent.LOOKUP)"lookupWire" else "sealWire"
            val go=AdminLayerJson.document(text(sample.value.getValue(key))).root.jsonObject
            must(go.keys==setOf("version","requestId","intent","originalBody64") && go["version"]==JsonPrimitive(1),"go_outer_closed")
            val outerId=text(go.getValue("requestId"))
            must(outerId==Identity.hash("synthetic-reconcile/${sample.name}/${intent.wire}".toByteArray()),"go_outer_identity")
            val request=AdminOperationReconcile.request(f.original(sample),f.actor,f.origin,outerId,intent)
            val ours=AdminLayerJson.document(request.wireJson()).root.jsonObject
            must(ours==go && text(go.getValue("intent"))==intent.wire,"go_outer_semantics")
            must(Policy.decode64(text(go.getValue("originalBody64"))).contentEquals(sample.raw),"go_outer_original_bytes")
            must(request.bodyBytes().size<350000 && request.uri==f.origin+AdminOperationReconcile.PATH,"go_outer_fixed_route")
        }
    }

    @Test fun allThirtySixActualGoOutcomesParseWithoutManufacturingLegacyAbsenceOrEffects() {
        val f=Corpus();val counts=mutableMapOf<AdminOperationOutcome,Int>();var total=0
        for(sample in f.samples) {
            val request=f.request(sample)
            for(entry in sample.outcomes) {
                val raw=text(entry.getValue("wire"));val receipt=AdminOperationReconcile.parseReply(request,raw,f.time)
                total++;counts[receipt.outcome]=(counts[receipt.outcome]?:0)+1
                must(receipt.wireJson()==raw && receipt.bodyHash==request.originalBodyHash && receipt.requestId==sample.requestId,"go_receipt_exact")
                must(receipt.actor==f.actor && receipt.targetId==f.proposal.targetId && receipt.targetKind==f.proposal.targetKind,"go_receipt_scope")
                if(receipt.outcome in listOf(AdminOperationOutcome.UNKNOWN,AdminOperationOutcome.NO_EFFECT)) {
                    must(receipt.effectId.isEmpty() && receipt.effectKind.isEmpty() && receipt.effectRevision==0L && receipt.job==null,"go_absence_has_no_effect")
                    must(receipt.outcome!=AdminOperationOutcome.NO_EFFECT || sample.version==2,"go_v1_no_effect")
                }else {
                    must(receipt.effectId==request.effectId && receipt.effectRevision==request.effectRevision,"go_receipt_reference")
                    if(request.effectKind=="job" && receipt.outcome==AdminOperationOutcome.RECORDED)must(receipt.job?.id==request.effectId,"go_recorded_job")
                    if(receipt.outcome==AdminOperationOutcome.RECORDED_RESULT_UNAVAILABLE)must(receipt.job==null,"go_unavailable_has_no_job")
                }
            }
            if(sample.version==1) {
                val absent=AdminLayerJson.document(text(sample.outcomes.single {text(it.getValue("name"))=="UNKNOWN"}.getValue("wire"))).root.jsonObject
                val forged=JsonObject(absent+mapOf("outcome" to JsonPrimitive("NO_EFFECT"),"recordedAtMs" to JsonPrimitive(f.now+1)))
                invalid {AdminOperationReconcile.parseReply(request,forged.toString(),f.time)}
            }
        }
        must(total==36 && counts[AdminOperationOutcome.UNKNOWN]==8 && counts[AdminOperationOutcome.NO_EFFECT]==4 && counts[AdminOperationOutcome.RECORDED]==16 && counts[AdminOperationOutcome.RECORDED_RESULT_UNAVAILABLE]==8,"go_receipt_matrix")
    }

    @Test fun actualGoPreviewSignaturesVerifyAgainstOnlyTheirEphemeralPublicSpki() {
        val f=Corpus();val public=f.publicKey()
        for(version in 1..2) {
            val sample=f.sample(version,AdminLayerAction.PUBLISH)
            val payload=sample.envelope.getValue("payload").jsonObject
            val ticket=text(payload.getValue("ticket"));val parts=ticket.split('.')
            must(verifies(ticket,public),"go_real_signature")
            val header=AdminLayerJson.parse(Policy.utf8(Policy.decode64(parts[0]))).jsonObject
            must(header.keys==setOf("alg","typ","kid") && text(header.getValue("alg"))=="ES256" && text(header.getValue("typ"))=="syn443-configuration-preview+jws" && text(header.getValue("kid"))==text(f.root.getValue("previewKeyId")),"go_ticket_header")
            val value=AdminLayerJson.parse(Policy.utf8(Policy.decode64(parts[1]))).jsonObject
            val preview=f.sample(version,AdminLayerAction.PREVIEW)
            must(text(value.getValue("origin"))==f.origin && text(value.getValue("actor"))==f.actor && text(value.getValue("requestId"))==preview.requestId,"go_ticket_context")
            must(text(payload.getValue("previewId"))==Identity.hash((f.actor+"\u0000"+preview.requestId).toByteArray()),"go_ticket_preview_id")
            must(text(value.getValue("draftHash"))==hash(f.proposal.wireJson().toByteArray()) && text(value.getValue("draftId"))==f.proposal.draftId,"go_ticket_proposal")
            must(value.getValue("issuedAtMs").jsonPrimitive.long==f.now && value.getValue("expiresAtMs").jsonPrimitive.long==f.now+120000,"go_ticket_time")
            val zero=parts[0]+"."+parts[1]+"."+Identity.encode(ByteArray(64))
            must(!verifies(zero,public),"go_zero_signature")
            val changed=Policy.decode64(parts[1]);changed[0]=(changed[0].toInt() xor 1).toByte()
            must(!verifies(parts[0]+"."+Identity.encode(changed)+"."+parts[2],public),"go_changed_message")
            must(!verifies(ticket,AdminControlFixture.ec().public as ECPublicKey),"go_foreign_public_key")
        }
    }

    @Test fun retainedGoPreviewAndPublicationMetadataCannotPromoteRestoredAuthority() {
        val f=Corpus()
        for(version in 1..2) {
            val sample=f.sample(version,AdminLayerAction.PREVIEW);val request=f.request(sample)
            val entry=sample.outcomes.single {text(it.getValue("name"))=="RECORDED_READY"}
            val raw=text(entry.getValue("wire"));val receipt=AdminOperationReconcile.parseReply(request,raw,f.time)
            val historical=checkNotNull(AdminOperationReconcile.historicalJob(request,receipt,f.time))
            val preview=checkNotNull(historical.preview)
            must(preview.replayOnly && request.original.expected.replayOnly && receipt.job?.state==AdminOperationJobState.READY,"go_retained_only")
            invalid {AdminLayerControl.publish(preview,f.actor,f.origin,Identity.random(),f.time,2)}
            val context=AdminLayerControl.replayContext(request.original,f.actor,f.origin)
            invalid {AdminLayerControl.restoreRequest(sample.raw,context,f.proposal.wireJson(),f.actor,f.origin)}
            val publication=f.sample(version,AdminLayerAction.PUBLISH);val published=f.request(publication)
            val terminal=publication.outcomes.single {text(it.getValue("name"))=="RECORDED_PUBLISHED"}
            val value=AdminOperationReconcile.parseReply(published,text(terminal.getValue("wire")),f.time)
            must(value.job?.state==AdminOperationJobState.PUBLISHED && published.original.expected.replayOnly,"go_publication_history_only")
            must(value.toString()=="AdminOperationReceipt([redacted])" && value.job.toString()=="AdminOperationJob([redacted])","go_history_redacted")
            val heads=checkNotNull(AdminOperationReconcile.historicalJob(published,value,f.time)).heads
            must(heads.size==1 && heads.single().revision==8L && heads.single().hash==hash(f.proposal.wireJson().toByteArray()),"go_published_heads_context")
            invalid {AdminOperationReconcile.historicalJob(published,receipt,f.time)}
            // Derived boundary mutations are not additional Go output vectors.
            val ready=AdminLayerJson.document(raw).root.jsonObject
            val missing=JsonObject(ready+mapOf("job" to JsonObject(ready.getValue("job").jsonObject-"result"))).toString()
            val incomplete=AdminOperationReconcile.parseReply(request,missing,f.time)
            invalid {AdminOperationReconcile.historicalJob(request,incomplete,f.time)}
            must(incomplete.wireJson()==missing && receipt.wireJson()==raw && request.original.bodyBytes().contentEquals(sample.raw),"go_missing_result_no_mutation")
            val queued=AdminLayerJson.document(text(sample.outcomes.single {text(it.getValue("name"))=="RECORDED"}.getValue("wire"))).root.jsonObject
            fun state(name:String,error:String?=null):AdminOperationReceipt {
                val job=queued.getValue("job").jsonObject
                val extra=if(error==null)emptyMap<String,JsonElement>() else mapOf("error" to JsonPrimitive(error))
                val replacement=JsonObject(job+mapOf("state" to JsonPrimitive(name))+extra)
                return AdminOperationReconcile.parseReply(request,JsonObject(queued+mapOf("job" to replacement)).toString(),f.time)
            }
            val expired=state("expired","deadline_or_retry_limit")
            val stopped=checkNotNull(AdminOperationReconcile.historicalJob(request,expired,f.time))
            must(stopped.state=="expired" && stopped.error=="deadline_or_retry_limit" && stopped.preview==null && stopped.heads.isEmpty(),"go_terminal_historical_error")
            invalid {AdminLayerControl.parseReply(request.original,checkNotNull(expired.job).wireJson(),f.time)}
            val legacy=state("applied")
            must(legacy.job?.state==AdminOperationJobState.LEGACY_APPLIED && AdminOperationReconcile.historicalJob(request,legacy,f.time)==null,"go_legacy_not_activation")
        }
    }
}
